import java.util.Scanner;

public class Main {
    static long fastPow(long base, long exp, long mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int P = sc.nextInt();
        int K = sc.nextInt();

        final long MOD = 1000000007;

        if (K == 0) {
            System.out.println(fastPow(P, P - 1, MOD));
            return;
        }
        if (K == 1) {
            System.out.println(fastPow(P, P, MOD));
            return;
        }

        boolean[] visited = new boolean[P];
        int cycleCount = 0;
        int current = 1;
        while (!visited[current]) {
            visited[current] = true;
            cycleCount++;
            current = (int)((long)K * current % P);
        }

        System.out.println(fastPow(P, cycleCount, MOD));
    }
}
